"""Editable connector family data: JST PH/XH new mountings, 2.54 mm
right-angle headers and the dual-row ICSP header.

Package drawings are true-scale top views extracted from the official
KiCad footprint masters (F.Fab body outline, numbered signal pads and
mounting pads), the same approach as the JST data module. Values are
literals on purpose so populate never depends on a local KiCad install.

Right-angle 2.54 mm headers come in two moulding positions, named after
the pin side the plastic sits on:

- through_hole_right_angle_short_pin: plastic on the short-pin side;
  the short legs enter the board and the long legs carry the signal row.
- through_hole_right_angle_long_pin: plastic on the long-pin side;
  the long legs enter the board, lifting the plastic clear of the board.
"""

